  INSERT INTO "Category" ("name", "slug", "description", "type", "icon", "sortOrder", "i18n", "legacySlugs")
  VALUES
  ('Quality of Life', 'quality-of-life', 'Small fixes and conveniences that smooth out everyday survival.', 'Mod', 'lucide:wand-sparkles', 1, '{"en":{"name":"Quality of Life","description":"Small fixes and conveniences that smooth out everyday survival."},"es":{"name":"Calidad de vida","description":"Arreglos y comodidades que hacen más llevadera la supervivencia diaria."},"de":{"name":"Komfort","description":"Kleine Verbesserungen und Komfortfunktionen für den Überlebensalltag."},"fr":{"name":"Qualité de vie","description":"Petites corrections et commodités qui facilitent la survie au quotidien."},"it":{"name":"Qualità della vita","description":"Piccole correzioni e comodità che semplificano la sopravvivenza di ogni giorno."},"nl":{"name":"Gebruiksgemak","description":"Kleine verbeteringen en gemakken die het dagelijkse overleven soepeler maken."},"pl":{"name":"Udogodnienia","description":"Drobne poprawki i udogodnienia, które ułatwiają codzienne przetrwanie."},"pt-BR":{"name":"Qualidade de vida","description":"Pequenas correções e facilidades que deixam a sobrevivência do dia a dia mais tranquila."},"ru":{"name":"Удобство","description":"Небольшие исправления и удобства, которые облегчают повседневное выживание."},"sv":{"name":"Livskvalitet","description":"Små fixar och bekvämligheter som gör vardagsöverlevnaden smidigare."},"tr":{"name":"Yaşam kalitesi","description":"Günlük hayatta kalmayı kolaylaştıran küçük düzeltmeler ve kolaylıklar."},"zh-Hans":{"name":"便利改进","description":"让日常生存更顺畅的小修复与便利功能。"},"ja":{"name":"快適性向上","description":"日々のサバイバルを快適にする小さな修正や便利機能。"}}'::jsonb, ARRAY['qol']::text[]),
  ('Gameplay & Difficulty', 'gameplay', 'New mechanics, balance changes and difficulty tweaks.', 'Mod', 'lucide:swords', 2, '{"en":{"name":"Gameplay & Difficulty","description":"New mechanics, balance changes and difficulty tweaks."},"es":{"name":"Jugabilidad y dificultad","description":"Nuevas mecánicas, cambios de equilibrio y ajustes de dificultad."},"de":{"name":"Gameplay & Schwierigkeit","description":"Neue Mechaniken, Balance-Änderungen und Anpassungen der Schwierigkeit."},"fr":{"name":"Gameplay et difficulté","description":"Nouvelles mécaniques, rééquilibrages et réglages de difficulté."},"it":{"name":"Gameplay e difficoltà","description":"Nuove meccaniche, bilanciamenti e regolazioni della difficoltà."},"nl":{"name":"Gameplay en moeilijkheid","description":"Nieuwe mechanieken, balanswijzigingen en aanpassingen aan de moeilijkheid."},"pl":{"name":"Rozgrywka i trudność","description":"Nowe mechaniki, zmiany balansu i ustawienia poziomu trudności."},"pt-BR":{"name":"Jogabilidade e dificuldade","description":"Novas mecânicas, ajustes de balanceamento e de dificuldade."},"ru":{"name":"Геймплей и сложность","description":"Новые механики, изменения баланса и настройки сложности."},"sv":{"name":"Spelupplägg och svårighet","description":"Nya mekaniker, balansändringar och justeringar av svårighetsgraden."},"tr":{"name":"Oynanış ve zorluk","description":"Yeni mekanikler, denge değişiklikleri ve zorluk ayarları."},"zh-Hans":{"name":"玩法与难度","description":"新机制、平衡调整与难度设置。"},"ja":{"name":"ゲームプレイと難易度","description":"新しいメカニクス、バランス調整、難易度の変更。"}}'::jsonb, '{}'::text[]),
  ('Building', 'building', 'More pieces, smarter tools and more freedom for your base.', 'Mod', 'lucide:hammer', 3, '{"en":{"name":"Building","description":"More pieces, smarter tools and more freedom for your base."},"es":{"name":"Construcción","description":"Más piezas, herramientas más inteligentes y más libertad para tu base."},"de":{"name":"Bauen","description":"Mehr Bauteile, klügere Werkzeuge und mehr Freiheit für deine Basis."},"fr":{"name":"Construction","description":"Plus de pièces, des outils plus malins et plus de liberté pour ta base."},"it":{"name":"Costruzione","description":"Più pezzi, strumenti più intelligenti e più libertà per la tua base."},"nl":{"name":"Bouwen","description":"Meer onderdelen, slimmer gereedschap en meer vrijheid voor je basis."},"pl":{"name":"Budowanie","description":"Więcej elementów, sprytniejsze narzędzia i większa swoboda przy budowie bazy."},"pt-BR":{"name":"Construção","description":"Mais peças, ferramentas mais espertas e mais liberdade para a sua base."},"ru":{"name":"Строительство","description":"Больше деталей, удобные инструменты и больше свободы для вашей базы."},"sv":{"name":"Byggande","description":"Fler byggdelar, smartare verktyg och mer frihet för din bas."},"tr":{"name":"İnşa","description":"Üssün için daha fazla parça, daha akıllı araçlar ve daha fazla özgürlük."},"zh-Hans":{"name":"建造","description":"更多建筑部件、更聪明的工具，让基地设计更自由。"},"ja":{"name":"建築","description":"拠点づくりのためのパーツ追加、便利なツール、自由度の向上。"}}'::jsonb, '{}'::text[]),
  ('Companions', 'companions', 'Kelvin, Virginia and everyone who keeps you company on the island.', 'Mod', 'lucide:heart-handshake', 4, '{"en":{"name":"Companions","description":"Kelvin, Virginia and everyone who keeps you company on the island."},"es":{"name":"Compañeros","description":"Kelvin, Virginia y todos los que te acompañan en la isla."},"de":{"name":"Begleiter","description":"Kelvin, Virginia und alle, die dir auf der Insel Gesellschaft leisten."},"fr":{"name":"Compagnons","description":"Kelvin, Virginia et tous ceux qui t''accompagnent sur l''île."},"it":{"name":"Compagni","description":"Kelvin, Virginia e chiunque ti faccia compagnia sull''isola."},"nl":{"name":"Metgezellen","description":"Kelvin, Virginia en iedereen die je gezelschap houdt op het eiland."},"pl":{"name":"Towarzysze","description":"Kelvin, Virginia i wszyscy, którzy dotrzymują ci towarzystwa na wyspie."},"pt-BR":{"name":"Companheiros","description":"Kelvin, Virginia e todos que fazem companhia a você na ilha."},"ru":{"name":"Спутники","description":"Кельвин, Вирджиния и все, кто составляет вам компанию на острове."},"sv":{"name":"Följeslagare","description":"Kelvin, Virginia och alla som håller dig sällskap på ön."},"tr":{"name":"Yol arkadaşları","description":"Kelvin, Virginia ve adada sana eşlik eden herkes."},"zh-Hans":{"name":"同伴","description":"Kelvin、Virginia 以及岛上陪伴你的所有伙伴。"},"ja":{"name":"仲間","description":"ケルビン、バージニアなど、島で一緒に過ごす仲間たち。"}}'::jsonb, '{}'::text[]),
  ('Weapons & Gear', 'weapons-gear', 'Weapons, tools, armor and everything you carry.', 'Mod', 'lucide:crosshair', 5, '{"en":{"name":"Weapons & Gear","description":"Weapons, tools, armor and everything you carry."},"es":{"name":"Armas y equipo","description":"Armas, herramientas, armaduras y todo lo que llevas encima."},"de":{"name":"Waffen & Ausrüstung","description":"Waffen, Werkzeuge, Rüstungen und alles, was du bei dir trägst."},"fr":{"name":"Armes et équipement","description":"Armes, outils, armures et tout ce que tu portes sur toi."},"it":{"name":"Armi ed equipaggiamento","description":"Armi, attrezzi, armature e tutto ciò che porti con te."},"nl":{"name":"Wapens en uitrusting","description":"Wapens, gereedschap, pantser en alles wat je bij je draagt."},"pl":{"name":"Broń i ekwipunek","description":"Broń, narzędzia, pancerze i wszystko, co nosisz przy sobie."},"pt-BR":{"name":"Armas e equipamento","description":"Armas, ferramentas, armaduras e tudo o que você carrega."},"ru":{"name":"Оружие и снаряжение","description":"Оружие, инструменты, броня и всё, что вы носите с собой."},"sv":{"name":"Vapen och utrustning","description":"Vapen, verktyg, rustningar och allt du bär med dig."},"tr":{"name":"Silahlar ve teçhizat","description":"Silahlar, aletler, zırhlar ve üzerinde taşıdığın her şey."},"zh-Hans":{"name":"武器与装备","description":"武器、工具、护甲以及你随身携带的一切。"},"ja":{"name":"武器と装備","description":"武器、道具、防具など、持ち歩くものすべて。"}}'::jsonb, '{}'::text[]),
  ('Vehicles & Movement', 'vehicles-movement', 'Getting around the island: vehicles, gliders, ziplines and traversal.', 'Mod', 'lucide:car', 6, '{"en":{"name":"Vehicles & Movement","description":"Getting around the island: vehicles, gliders, ziplines and traversal."},"es":{"name":"Vehículos y movimiento","description":"Moverse por la isla: vehículos, planeadores, tirolinas y desplazamiento."},"de":{"name":"Fahrzeuge & Bewegung","description":"Unterwegs auf der Insel: Fahrzeuge, Gleiter, Seilrutschen und Fortbewegung."},"fr":{"name":"Véhicules et déplacements","description":"Se déplacer sur l''île : véhicules, planeurs, tyroliennes et déplacements."},"it":{"name":"Veicoli e movimento","description":"Muoversi sull''isola: veicoli, deltaplani, teleferiche e spostamenti."},"nl":{"name":"Voertuigen en beweging","description":"Over het eiland reizen: voertuigen, zweefvliegers, tokkelbanen en verplaatsing."},"pl":{"name":"Pojazdy i poruszanie się","description":"Podróżowanie po wyspie: pojazdy, lotnie, tyrolki i przemieszczanie się."},"pt-BR":{"name":"Veículos e movimentação","description":"Como se locomover pela ilha: veículos, planadores, tirolesas e deslocamento."},"ru":{"name":"Транспорт и передвижение","description":"Передвижение по острову: транспорт, дельтапланы, канатные дороги и не только."},"sv":{"name":"Fordon och förflyttning","description":"Ta dig runt på ön: fordon, glidflygare, linbanor och förflyttning."},"tr":{"name":"Araçlar ve hareket","description":"Adada dolaşmak: araçlar, planörler, zip hatları ve hareket."},"zh-Hans":{"name":"载具与移动","description":"在岛上穿行：载具、滑翔翼、滑索与移动方式。"},"ja":{"name":"乗り物と移動","description":"島を移動する手段：乗り物、グライダー、ジップラインなど。"}}'::jsonb, '{}'::text[]),
  ('Model Swap', 'model-swap', 'Replace characters, creatures and items with new models and skins.', 'Mod', 'lucide:shirt', 7, '{"en":{"name":"Model Swap","description":"Replace characters, creatures and items with new models and skins."},"es":{"name":"Cambio de modelos","description":"Sustituye personajes, criaturas y objetos por nuevos modelos y aspectos."},"de":{"name":"Modelltausch","description":"Ersetze Figuren, Kreaturen und Gegenstände durch neue Modelle und Skins."},"fr":{"name":"Changement de modèles","description":"Remplace personnages, créatures et objets par de nouveaux modèles et skins."},"it":{"name":"Sostituzione modelli","description":"Sostituisci personaggi, creature e oggetti con nuovi modelli e skin."},"nl":{"name":"Modelwissel","description":"Vervang personages, wezens en voorwerpen door nieuwe modellen en skins."},"pl":{"name":"Podmiana modeli","description":"Zamień postacie, stworzenia i przedmioty na nowe modele i skórki."},"pt-BR":{"name":"Troca de modelos","description":"Substitua personagens, criaturas e itens por novos modelos e skins."},"ru":{"name":"Замена моделей","description":"Замена персонажей, существ и предметов на новые модели и скины."},"sv":{"name":"Modellbyte","description":"Byt ut karaktärer, varelser och föremål mot nya modeller och skins."},"tr":{"name":"Model değişimi","description":"Karakterleri, yaratıkları ve eşyaları yeni modeller ve kaplamalarla değiştir."},"zh-Hans":{"name":"模型替换","description":"用新模型和皮肤替换角色、生物与物品。"},"ja":{"name":"モデル差し替え","description":"キャラクター、クリーチャー、アイテムを新しいモデルやスキンに置き換え。"}}'::jsonb, '{}'::text[]),
  ('UI & HUD', 'ui-hud', 'HUD elements, overlays, indicators and interface tweaks.', 'Mod', 'lucide:panels-top-left', 8, '{"en":{"name":"UI & HUD","description":"HUD elements, overlays, indicators and interface tweaks."},"es":{"name":"Interfaz y HUD","description":"Elementos del HUD, superposiciones, indicadores y ajustes de la interfaz."},"de":{"name":"UI & HUD","description":"HUD-Elemente, Overlays, Anzeigen und Anpassungen der Oberfläche."},"fr":{"name":"Interface et HUD","description":"Éléments du HUD, surcouches, indicateurs et retouches de l''interface."},"it":{"name":"Interfaccia e HUD","description":"Elementi dell''HUD, overlay, indicatori e ritocchi all''interfaccia."},"nl":{"name":"Interface en HUD","description":"HUD-elementen, overlays, indicatoren en aanpassingen aan de interface."},"pl":{"name":"Interfejs i HUD","description":"Elementy HUD, nakładki, wskaźniki i poprawki interfejsu."},"pt-BR":{"name":"Interface e HUD","description":"Elementos do HUD, sobreposições, indicadores e ajustes na interface."},"ru":{"name":"Интерфейс и HUD","description":"Элементы HUD, оверлеи, индикаторы и доработки интерфейса."},"sv":{"name":"Gränssnitt och HUD","description":"HUD-element, överlägg, indikatorer och justeringar av gränssnittet."},"tr":{"name":"Arayüz ve HUD","description":"HUD öğeleri, katmanlar, göstergeler ve arayüz düzenlemeleri."},"zh-Hans":{"name":"界面与 HUD","description":"HUD 元素、叠加层、指示器与界面调整。"},"ja":{"name":"UI と HUD","description":"HUD 要素、オーバーレイ、インジケーター、インターフェースの調整。"}}'::jsonb, '{}'::text[]),
  ('Menus & Sandbox', 'menus-sandbox', 'Mod menus, spawners and creative tools to play your own way.', 'Mod', 'lucide:sliders-horizontal', 9, '{"en":{"name":"Menus & Sandbox","description":"Mod menus, spawners and creative tools to play your own way."},"es":{"name":"Menús y sandbox","description":"Menús de mods, generadores y herramientas creativas para jugar a tu manera."},"de":{"name":"Menüs & Sandbox","description":"Mod-Menüs, Spawner und kreative Werkzeuge, um auf deine Art zu spielen."},"fr":{"name":"Menus et bac à sable","description":"Menus de mods, générateurs d''objets et outils créatifs pour jouer à ta façon."},"it":{"name":"Menu e sandbox","description":"Menu mod, spawner e strumenti creativi per giocare a modo tuo."},"nl":{"name":"Menu''s en sandbox","description":"Modmenu''s, spawners en creatieve tools om op jouw manier te spelen."},"pl":{"name":"Menu i sandbox","description":"Menu modów, spawnery i narzędzia kreatywne do gry po swojemu."},"pt-BR":{"name":"Menus e sandbox","description":"Menus de mods, spawners e ferramentas criativas para jogar do seu jeito."},"ru":{"name":"Меню и песочница","description":"Мод-меню, спавнеры и творческие инструменты, чтобы играть по-своему."},"sv":{"name":"Menyer och sandlåda","description":"Moddmenyer, spawners och kreativa verktyg för att spela på ditt sätt."},"tr":{"name":"Menüler ve sandbox","description":"Mod menüleri, spawner''lar ve kendi tarzında oynaman için yaratıcı araçlar."},"zh-Hans":{"name":"菜单与沙盒","description":"模组菜单、生成器和创意工具，按你的方式游玩。"},"ja":{"name":"メニューとサンドボックス","description":"Mod メニュー、スポナー、自分流に遊ぶためのクリエイティブツール。"}}'::jsonb, '{}'::text[]),
  ('Multiplayer & Servers', 'multiplayer-servers', 'Co-op improvements, dedicated servers and admin tools.', 'Mod', 'lucide:server', 10, '{"en":{"name":"Multiplayer & Servers","description":"Co-op improvements, dedicated servers and admin tools."},"es":{"name":"Multijugador y servidores","description":"Mejoras del cooperativo, servidores dedicados y herramientas de administración."},"de":{"name":"Mehrspieler & Server","description":"Verbesserungen für Koop, dedizierte Server und Admin-Werkzeuge."},"fr":{"name":"Multijoueur et serveurs","description":"Améliorations du coop, serveurs dédiés et outils d''administration."},"it":{"name":"Multigiocatore e server","description":"Miglioramenti alla cooperativa, server dedicati e strumenti di amministrazione."},"nl":{"name":"Multiplayer en servers","description":"Verbeteringen voor co-op, dedicated servers en beheertools."},"pl":{"name":"Wieloosobowe i serwery","description":"Usprawnienia trybu co-op, serwery dedykowane i narzędzia administracyjne."},"pt-BR":{"name":"Multijogador e servidores","description":"Melhorias no cooperativo, servidores dedicados e ferramentas de administração."},"ru":{"name":"Мультиплеер и серверы","description":"Улучшения кооператива, выделенные серверы и инструменты администратора."},"sv":{"name":"Flerspelare och servrar","description":"Förbättringar för co-op, dedikerade servrar och adminverktyg."},"tr":{"name":"Çok oyunculu ve sunucular","description":"Co-op iyileştirmeleri, özel sunucular ve yönetici araçları."},"zh-Hans":{"name":"多人与服务器","description":"合作模式改进、专用服务器与管理工具。"},"ja":{"name":"マルチプレイとサーバー","description":"協力プレイの改善、専用サーバー、管理ツール。"}}'::jsonb, '{}'::text[]),
  ('Library', 'library', 'Shared code other mods depend on. Install them when a mod asks for them.', 'Mod', 'lucide:library-big', 11, '{"en":{"name":"Libraries","description":"Shared code other mods depend on. Install them when a mod asks for them."},"es":{"name":"Librerías","description":"Código compartido del que dependen otros mods. Instálalas cuando un mod las pida."},"de":{"name":"Bibliotheken","description":"Gemeinsamer Code, den andere Mods brauchen. Installiere sie, wenn ein Mod danach verlangt."},"fr":{"name":"Bibliothèques","description":"Du code partagé dont d''autres mods dépendent. Installe-les quand un mod les demande."},"it":{"name":"Librerie","description":"Codice condiviso da cui dipendono altre mod. Installale quando una mod le richiede."},"nl":{"name":"Bibliotheken","description":"Gedeelde code waar andere mods van afhangen. Installeer ze wanneer een mod erom vraagt."},"pl":{"name":"Biblioteki","description":"Wspólny kod, od którego zależą inne mody. Zainstaluj je, gdy mod ich wymaga."},"pt-BR":{"name":"Bibliotecas","description":"Código compartilhado do qual outros mods dependem. Instale quando um mod pedir."},"ru":{"name":"Библиотеки","description":"Общий код, от которого зависят другие моды. Устанавливайте, когда мод их требует."},"sv":{"name":"Bibliotek","description":"Delad kod som andra moddar är beroende av. Installera dem när en modd kräver det."},"tr":{"name":"Kütüphaneler","description":"Diğer modların bağlı olduğu ortak kod. Bir mod istediğinde yükle."},"zh-Hans":{"name":"依赖库","description":"其他模组依赖的共享代码。当模组需要时再安装。"},"ja":{"name":"ライブラリ","description":"他の Mod が依存する共有コード。Mod に求められたときにインストールします。"}}'::jsonb, '{}'::text[]),
  ('Misc', 'misc', 'Everything that doesn''t fit anywhere else.', 'Mod', 'lucide:shapes', 12, '{"en":{"name":"Other","description":"Everything that doesn''t fit anywhere else."},"es":{"name":"Otros","description":"Todo lo que no encaja en ninguna otra categoría."},"de":{"name":"Sonstiges","description":"Alles, was nirgendwo sonst hineinpasst."},"fr":{"name":"Autres","description":"Tout ce qui ne rentre dans aucune autre catégorie."},"it":{"name":"Altro","description":"Tutto ciò che non rientra in nessun''altra categoria."},"nl":{"name":"Overig","description":"Alles wat nergens anders in past."},"pl":{"name":"Inne","description":"Wszystko, co nie pasuje nigdzie indziej."},"pt-BR":{"name":"Outros","description":"Tudo o que não se encaixa em outra categoria."},"ru":{"name":"Другое","description":"Всё, что не подходит под другие категории."},"sv":{"name":"Övrigt","description":"Allt som inte passar in någon annanstans."},"tr":{"name":"Diğer","description":"Başka hiçbir yere uymayan her şey."},"zh-Hans":{"name":"其他","description":"不属于其他任何分类的内容。"},"ja":{"name":"その他","description":"ほかのどのカテゴリーにも当てはまらないもの。"}}'::jsonb, '{}'::text[])
